package com.tripmateai.controller; import com.tripmateai.dto.request.auth.*; import com.tripmateai.dto.response.*; import com.tripmateai.dto.response.auth.AuthResponse; import com.tripmateai.dto.response.user.UserProfileResponse; import com.tripmateai.service.*; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/auth") @RequiredArgsConstructor public class AuthController {private final AuthService auth;private final PasswordResetService reset; @PostMapping("/register") public ResponseEntity<ApiResponse<AuthResponse>> register(@Valid @RequestBody RegisterRequest r){return ResponseUtils.created(auth.register(r),"Registration successful");} @PostMapping("/login") public ResponseEntity<ApiResponse<AuthResponse>> login(@Valid @RequestBody LoginRequest r){return ResponseUtils.success(auth.login(r),"Login successful");} @PostMapping("/refresh") public ResponseEntity<ApiResponse<AuthResponse>> refresh(@Valid @RequestBody RefreshTokenRequest r){return ResponseUtils.success(auth.refresh(r),"Token refreshed");} @PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) public void logout(@Valid @RequestBody RefreshTokenRequest r){auth.logout(r);} @PostMapping("/forgot-password") public ResponseEntity<ApiResponse<String>> forgot(@Valid @RequestBody ForgotPasswordRequest r){return ResponseUtils.success(reset.create(r),"Development reset token generated");} @PostMapping("/reset-password") public ResponseEntity<ApiResponse<Void>> reset(@Valid @RequestBody ResetPasswordRequest r){reset.reset(r);return ResponseUtils.success(null,"Password reset successful");} @PostMapping("/change-password") public ResponseEntity<ApiResponse<Void>> change(@Valid @RequestBody ChangePasswordRequest r){reset.change(r);return ResponseUtils.success(null,"Password changed successfully");} @GetMapping("/me") public ResponseEntity<ApiResponse<UserProfileResponse>> me(){return ResponseUtils.success(auth.me(),"Current user");}}
